import { useState, useCallback, useEffect, useRef } from "react";
import { Chip } from "@/shared/ui/data/Chip";
import { Button } from "@/shared/ui/controls/Button";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

// A component composing multiple first-party FEATURE-level sibling cross-imports (StageScreenFrame,
// PreviewFrame) reliably fails to build in this sandbox — same limit ClaudeConfigCard/PlannerLibraryPane
// hit. Inlined both bodies (+ StageScreenFrame's own IconButton dependency) locally instead.

// IconButton — inlined verbatim from the promoted `ui-icon-button` component (AS GRAPH SOURCE leaf).
const CLOSE_GLYPH = "✕";
function IconButton({ "aria-label": ariaLabel, onClick, children, size = "md", danger, disabled, title, className, style }) {
  const cls = ["icon-btn", size !== "md" && size, danger && "danger", className].filter(Boolean).join(" ");
  return (
    <button type="button" className={cls} aria-label={ariaLabel} title={title ?? ariaLabel} onClick={onClick} disabled={disabled} style={style}>
      {children ?? CLOSE_GLYPH}
    </button>
  );
}

// StageScreenFrame — inlined verbatim from the promoted `stagescreenframe` component.
function StageScreenFrame({ label, badge, statusLabel, statusColor, actions, onClose, footer, fullWidth, bare, children }) {
  return (
    <section style={{
      ...(fullWidth ? { flex: 1, minWidth: 0 } : { flex: "0 0 auto", width: 420, borderLeft: "1px solid var(--border-soft)" }),
      display: "flex", flexDirection: "column", minHeight: 0, overflow: "hidden", background: "var(--bg-panel)",
    }}>
      {!bare && (
        <Row className="mono" gap={8} style={{
          padding: "10px 14px", borderBottom: "1px solid var(--border-soft)",
          fontSize: 11, color: "var(--fg-muted)",
        }}>
          <Text as="span" tone="accent">▸ {label}</Text>
          {badge}
          <Box as="span" style={{ flex: 1 }} />
          {statusLabel && <Text as="span" size={10} style={{ color: statusColor ?? "var(--fg-dim)" }}>{statusLabel}</Text>}
          {actions}
          {onClose && <IconButton aria-label="Close" onClick={onClose} />}
        </Row>
      )}
      <Stack style={{ flex: 1, minHeight: 0 }}>{children}</Stack>
      {footer}
    </section>
  );
}

// PreviewFrame — inlined verbatim from the promoted `previewframe` component.
function Spinner({ size = 20 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true" style={{ animation: "bsc-preview-spin 0.8s linear infinite" }}>
      <circle cx="12" cy="12" r="9" fill="none" stroke="var(--fg-dim)" strokeWidth="2.5" strokeLinecap="round" strokeDasharray="34 100" opacity="0.7" />
      <style>{"@keyframes bsc-preview-spin{to{transform:rotate(360deg)}}"}</style>
    </svg>
  );
}
const DEMO_SRC_DOC = "<html><body style='margin:0;display:flex;align-items:center;justify-content:center;height:100vh;font:12px monospace;color:#888;background:#0b0e12'>preview target</body></html>";
function PreviewFrame({ srcDoc = DEMO_SRC_DOC, onStatus }) {
  const frameRef = useRef(null);
  const [phase, setPhase] = useState("loading");

  useEffect(() => { setPhase("loading"); }, [srcDoc]);
  useEffect(() => {
    function onMsg(e) {
      if (e.source !== frameRef.current?.contentWindow) return;
      const d = e.data;
      if (!d || typeof d !== "object") return;
      if (d.__preview === "ready") { setPhase("ready"); onStatus?.({ status: "ready" }); }
      else if (d.__preview === "error") { setPhase("error"); onStatus?.({ status: "error", message: String(d.message ?? "") }); }
    }
    window.addEventListener("message", onMsg);
    return () => window.removeEventListener("message", onMsg);
  }, [onStatus]);

  if (!srcDoc) return null;
  return (
    <div style={{ position: "relative", flex: 1, width: "100%", height: "100%" }}>
      <iframe ref={frameRef} title="UI preview" sandbox="allow-scripts" srcDoc={srcDoc}
        style={{ position: "absolute", inset: 0, width: "100%", height: "100%", border: "none", background: "var(--bg-canvas)" }} />
      {phase === "loading" && (
        <div aria-hidden style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", background: "var(--bg-canvas)", pointerEvents: "none" }}>
          <Spinner size={20} />
        </div>
      )}
    </div>
  );
}

// Vendored from `../preview/claudeDesignBrief` (unresolvable in this sandbox) — pure, unchanged.
function buildClaudeDesignBrief(screens, opts = {}) {
  const list = screens.length ? screens.map((s) => `- **${s}**`).join("\n") : "- (no screens defined yet — define them in the UI stage first)";
  const project = opts.projectName ? ` for ${opts.projectName}` : "";
  return `# Design brief${project}\n\nDesign these screens as polished, production-ready UI components:\n\n${list}`;
}

// Preview-only sample state standing in for the real `useAppStore` slices (stagePreview/stageRuns/
// uiScreens/uiApproved/setUiScreenApproved) and the render-preview dispatch pipeline — all app-internal,
// unresolvable in this sandbox.
const SAMPLE_DECLARED = ["Dashboard", "ProjectDetail", "Settings"];

export function PlanPreviewPane({ projectKey = "northwind", onClose }) {
  const [preview, setPreview] = useState({ mode: "2d", screen: "Dashboard", srcDoc: null });
  const [status, setStatus] = useState("idle");
  const [declared] = useState(SAMPLE_DECLARED);
  const [approvedList, setApprovedList] = useState(["Dashboard"]);
  const setUiScreenApproved = (pk, screen, on) => setApprovedList((a) => on ? [...a, screen] : a.filter((s) => s !== screen));
  const [frameError, setFrameError] = useState("");
  const [briefCopied, setBriefCopied] = useState(false);

  const currentScreen = preview?.screen;
  const currentApproved = !!currentScreen && approvedList.includes(currentScreen);
  const approvedCount = declared.filter((s) => approvedList.includes(s)).length;

  const renderDemo = () => setStatus("running");
  const loadSkeleton = () => setStatus("running");
  const onStatus = useCallback((s) => { setFrameError(s.status === "error" ? (s.message ?? "") : ""); }, []);

  const statusLabel = status === "running" ? "building…" : frameError ? "error" : status;
  const statusColor = frameError || status === "fail" ? "var(--danger)" : status === "ok" ? "var(--success)" : "var(--fg-dim)";

  return (
    <StageScreenFrame
      label="preview"
      badge={preview && <Chip style={{ fontSize: 9 }}>{preview.mode}</Chip>}
      statusLabel={statusLabel}
      statusColor={statusColor}
      onClose={onClose}
      actions={
        <>
          {preview && currentScreen && (
            <Button
              variant={currentApproved ? "default" : "ghost"}
              size="sm"
              onClick={() => setUiScreenApproved(projectKey, currentScreen, !currentApproved)}
              title={currentApproved ? `${currentScreen} approved — click to revoke` : `Approve ${currentScreen}`}
              style={currentApproved ? { color: "var(--success)", borderColor: "var(--success)" } : undefined}
            >
              {currentApproved ? "✓ approved" : "approve"}
            </Button>
          )}
          {preview && <Button variant="ghost" size="sm" onClick={renderDemo} title="Rebuild">↻</Button>}
        </>
      }
      footer={declared.length > 0 && (
        <Box pad={[8, 12]} style={{ borderTop: "1px solid var(--border-soft)", maxHeight: 180, overflow: "auto" }}>
          <Row className="mono" gap={8} style={{ fontSize: 10, color: "var(--fg-muted)", marginBottom: 6 }}>
            <Box as="span">screens</Box>
            <Button
              variant="ghost"
              size="sm"
              title="Copy a Claude Design prompt for these screens"
              onClick={() => {
                void navigator.clipboard?.writeText(buildClaudeDesignBrief(declared));
                setBriefCopied(true);
                setTimeout(() => setBriefCopied(false), 1600);
              }}
            >{briefCopied ? "✓ copied" : "✦ Claude Design brief"}</Button>
            <Box as="span" style={{ flex: 1 }} />
            <Text as="span" style={{ color: approvedCount === declared.length ? "var(--success)" : "var(--fg-dim)" }}>
              {approvedCount}/{declared.length} approved
            </Text>
          </Row>
          <Stack gap={2}>
            {declared.map((s) => {
              const ok = approvedList.includes(s);
              return (
                <Button
                  key={s}
                  variant="ghost"
                  size="sm"
                  className="mono"
                  onClick={() => setUiScreenApproved(projectKey, s, !ok)}
                  title={ok ? `${s} approved — click to revoke` : `Approve ${s}`}
                  style={{ display: "flex", alignItems: "center", gap: 8, justifyContent: "flex-start", textAlign: "left", fontSize: 11 }}
                >
                  <Text as="span" style={{ color: ok ? "var(--success)" : "var(--fg-dim)" }}>{ok ? "✓" : "○"}</Text>
                  <Text as="span" style={{ color: s === currentScreen ? "var(--accent)" : "var(--fg)" }}>{s}</Text>
                </Button>
              );
            })}
          </Stack>
        </Box>
      )}
    >
      <Stack style={{ flex: 1, minHeight: 0 }}>
        {status === "fail" ? (
          <Text as="div" mono size={11} tone="danger" style={{ padding: 16, whiteSpace: "pre-wrap", overflow: "auto" }}>
            Preview failed to build.
          </Text>
        ) : preview?.srcDoc ? (
          <PreviewFrame srcDoc={preview.srcDoc} onStatus={onStatus} />
        ) : (
          <Stack align="center" justify="center" gap={12} style={{ flex: 1, padding: 24, textAlign: "center" }}>
            <Text as="div" mono size={11.5} tone="muted">
              {status === "running" ? "Bundling…" : "No preview yet"}
            </Text>
            <Box className="hint" style={{ maxWidth: 280 }}>
              The UI stage renders generated screens here via the render-preview pipeline.
            </Box>
            <Row gap={8} align="stretch">
              <Button onClick={loadSkeleton} disabled={status === "running"}>load from skeleton →</Button>
              <Button variant="ghost" onClick={renderDemo} disabled={status === "running"}>demo</Button>
            </Row>
          </Stack>
        )}
      </Stack>
    </StageScreenFrame>
  );
}

